import matplotlib.pyplot as plt
plt.rcParams['font.sans-serif'] = ['Microsoft JhengHei']
from matplotlib.patches import Polygon
def draw(ax, x, y, s, depth):
    if depth==1:
        ax.add_patch(Polygon([[x,y],[x+s,y],[x+s/2,y+s*0.866]], fill=False, linewidth=1.5))
    else:
        draw(ax,x,y,s/2,depth-1); draw(ax,x+s/2,y,s/2,depth-1); draw(ax,x+s/4,y+s*0.433,s/2,depth-1)
fig, axes = plt.subplots(1,3,figsize=(7,2.3))
for n,ax in enumerate(axes,1):
    draw(ax,0,0,1,n); ax.set_xlim(-.05,1.05); ax.set_ylim(-.05,.95); ax.set_aspect('equal'); ax.axis('off'); ax.set_title(f'第 {n} 圖')
fig.tight_layout(); fig.savefig('output.png', dpi=180, transparent=True); plt.close(fig)

import matplotlib.pyplot as plt
plt.rcParams['font.sans-serif'] = ['Microsoft JhengHei']
fig, axes = plt.subplots(1, 3, figsize=(7, 2.5))
for n, ax in enumerate(axes, 1):
    for row in range(n):
        count=n-row
        start=row/2
        for j in range(count): ax.scatter(start+j, row*0.8, s=70)
    ax.set_aspect('equal'); ax.axis('off'); ax.set_title(f'第 {n} 層')
fig.tight_layout(); fig.savefig('output.png', dpi=180, transparent=True); plt.close(fig)

