    "concepts": [
      {
        "skeleton_id": "1-1-C01",
        "id": "concept-own-math2-1-1-c01",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "數列、項、索引與一般項",
        "summary_md": "數列是依固定次序排列的數；一般項同時描述項值規律與索引起點。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c01-b1",
            "position": 0,
            "block_type": "definition",
            "title": "數列語言",
            "content_md": "數列記作 $\\langle a_n\\rangle$，$a_1$ 為首項，$a_n$ 為第 $n$ 項。項的位置是資料的一部分。"
          },
          {
            "id": "concept-own-math2-1-1-c01-b2",
            "position": 1,
            "block_type": "method",
            "title": "雙向轉換",
            "content_md": "已知 $a_n$ 時依序代入 $n=1,2,\\ldots$；由前幾項找一般項時，分別檢查差、比、符號、分子分母及週期。"
          },
          {
            "id": "concept-own-math2-1-1-c01-b3",
            "position": 2,
            "block_type": "warning",
            "title": "索引起點",
            "content_md": "外觀相似的公式可能因 $n$、$n-1$ 或 $n+1$ 而表示不同數列；猜得公式後必須回代前幾項。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C02",
        "id": "concept-own-math2-1-1-c02",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "等差數列、一般項與參數反求",
        "summary_md": "相鄰差固定的數列為等差數列，可由任兩項反求首項與公差。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c02-b1",
            "position": 0,
            "block_type": "definition",
            "title": "固定差",
            "content_md": "若 $a_{n+1}-a_n=d$，則 $\\langle a_n\\rangle$ 為公差 $d$ 的等差數列。"
          },
          {
            "id": "concept-own-math2-1-1-c02-b2",
            "position": 1,
            "block_type": "formula",
            "title": "一般項",
            "content_md": "$a_n=a_1+(n-1)d,\\qquad a_q-a_p=(q-p)d.$"
          },
          {
            "id": "concept-own-math2-1-1-c02-b3",
            "position": 2,
            "block_type": "method",
            "title": "臨界項",
            "content_md": "求「從第幾項開始為正或負」時，先解嚴格不等式，再取符合條件的最小正整數。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C03",
        "id": "concept-own-math2-1-1-c03",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "等差中項與插項",
        "summary_md": "等距索引的等差數列具有對稱關係；插項時要先數清楚間隔數。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c03-b1",
            "position": 0,
            "block_type": "formula",
            "title": "等差中項",
            "content_md": "若 $a,b,c$ 成等差數列，則 $2b=a+c$。"
          },
          {
            "id": "concept-own-math2-1-1-c03-b2",
            "position": 1,
            "block_type": "method",
            "title": "插入中項",
            "content_md": "在兩端點間插入 $m$ 個等差中項時，共有 $m+1$ 個間隔。"
          },
          {
            "id": "concept-own-math2-1-1-c03-b3",
            "position": 2,
            "block_type": "note",
            "title": "對稱項",
            "content_md": "若索引到中央項的距離相同，則 $a_{m-r}+a_{m+r}=2a_m$。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C04",
        "id": "concept-own-math2-1-1-c04",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "等比數列、一般項、中項與參數反求",
        "summary_md": "相鄰比固定的非零數列為等比數列；反求公比時須處理正負根與符號條件。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c04-b1",
            "position": 0,
            "block_type": "definition",
            "title": "固定比",
            "content_md": "若各項及 $r$ 均非零，且 $\\frac{a_{n+1}}{a_n}=r$，則為公比 $r$ 的等比數列。"
          },
          {
            "id": "concept-own-math2-1-1-c04-b2",
            "position": 1,
            "block_type": "formula",
            "title": "一般項與中項",
            "content_md": "$a_n=a_1r^{n-1},\\qquad \\frac{a_q}{a_p}=r^{q-p},\\qquad b^2=ac.$"
          },
          {
            "id": "concept-own-math2-1-1-c04-b3",
            "position": 2,
            "block_type": "warning",
            "title": "正負根",
            "content_md": "由偶次方求 $r$ 時原則上有正、負兩根，必須用正項、單調或順序條件篩選。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C05",
        "id": "concept-own-math2-1-1-c05",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "混合條件與新數列性質",
        "summary_md": "等差、等比混合題先分別代數化；數列運算後的性質必須回到差或比檢查。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c05-b1",
            "position": 0,
            "block_type": "method",
            "title": "混合條件",
            "content_md": "先寫出 $2b=a+c$ 與 $b^2=ac$ 等關係，再聯立並檢查零值、正負與順序。"
          },
          {
            "id": "concept-own-math2-1-1-c05-b2",
            "position": 1,
            "block_type": "method",
            "title": "新數列",
            "content_md": "判斷新數列是否等差，計算相鄰差；判斷是否等比，計算相鄰比。"
          },
          {
            "id": "concept-own-math2-1-1-c05-b3",
            "position": 2,
            "block_type": "warning",
            "title": "反例",
            "content_md": "少數特例成立不能推出一般結論；錯誤敘述應以符合原條件的反例否定。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C06",
        "id": "concept-own-math2-1-1-c06",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "遞迴定義、逐項計算與型態辨認",
        "summary_md": "遞迴定義由初始值與產生後項的規則共同決定數列。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c06-b1",
            "position": 0,
            "block_type": "definition",
            "title": "完整遞迴定義",
            "content_md": "初始值、遞迴規則及規則適用範圍缺一不可。"
          },
          {
            "id": "concept-own-math2-1-1-c06-b2",
            "position": 1,
            "block_type": "method",
            "title": "逐項計算",
            "content_md": "求 $a_n$ 前須先得到它所依賴的前項，不可跳過依賴關係。"
          },
          {
            "id": "concept-own-math2-1-1-c06-b3",
            "position": 2,
            "block_type": "formula",
            "title": "基本型態",
            "content_md": "$a_n=a_{n-1}+d$ 為等差型；$a_n=ra_{n-1}$ 為等比型。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C07",
        "id": "concept-own-math2-1-1-c07",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "累加型與累乘型遞迴",
        "summary_md": "相鄰差可逐式相加，相鄰比可逐式相乘，並利用中間項消去。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c07-b1",
            "position": 0,
            "block_type": "method",
            "title": "累加",
            "content_md": "將 $a_k-a_{k-1}=f(k)$ 由 $k=2$ 寫到 $n$ 後相加，中間項會消去。"
          },
          {
            "id": "concept-own-math2-1-1-c07-b2",
            "position": 1,
            "block_type": "method",
            "title": "累乘",
            "content_md": "將 $\\frac{a_k}{a_{k-1}}=g(k)$ 逐式相乘，再整理分子分母的端點因子。"
          },
          {
            "id": "concept-own-math2-1-1-c07-b3",
            "position": 2,
            "block_type": "warning",
            "title": "上下限",
            "content_md": "展開時至少寫出前兩式與最後一式，以檢查是否多一項或少一項。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C08",
        "id": "concept-own-math2-1-1-c08",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "線性複合與可變換遞迴",
        "summary_md": "藉由固定點平移或倒數代換，可把非基本外觀轉成等差或等比數列。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c08-b1",
            "position": 0,
            "block_type": "formula",
            "title": "固定點平移",
            "content_md": "對 $a_{n+1}=pa_n+q$，取 $\\alpha=p\\alpha+q$，令 $b_n=a_n-\\alpha$，則 $b_{n+1}=pb_n$。"
          },
          {
            "id": "concept-own-math2-1-1-c08-b2",
            "position": 1,
            "block_type": "method",
            "title": "倒數代換",
            "content_md": "若分式遞迴含 $\\frac{a_n}{1+ca_n}$，可嘗試令 $b_n=\\frac{1}{a_n}$。"
          },
          {
            "id": "concept-own-math2-1-1-c08-b3",
            "position": 2,
            "block_type": "warning",
            "title": "還原條件",
            "content_md": "代換前後都要檢查分母非零，以及所得公式是否也適用首項。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C09",
        "id": "concept-own-math2-1-1-c09",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "由圖形定義數列並建立模型",
        "summary_md": "圖形規律題先定義計數量，再比較相鄰兩圖的新增量或倍率。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c09-b1",
            "position": 0,
            "block_type": "method",
            "title": "建模步驟",
            "content_md": "定義 $a_n$ 的計數對象，列出 $a_1,a_2,a_3$，比較 $a_n-a_{n-1}$ 或 $\\frac{a_n}{a_{n-1}}$，最後寫出含初始值的遞迴式。"
          },
          {
            "id": "concept-own-math2-1-1-c09-b2",
            "position": 1,
            "block_type": "warning",
            "title": "新增量與總量",
            "content_md": "圖上新增加的數量不等於該階段的總數；共用點、共用邊也不可重複計數。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C10",
        "id": "concept-own-math2-1-1-c10",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "歸納法的邏輯結構與證明診斷",
        "summary_md": "數學歸納法由起始步與可傳遞的歸納步共同構成。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c10-b1",
            "position": 0,
            "block_type": "method",
            "title": "四段書寫",
            "content_md": "驗證起始值；假設 $n=k$ 成立；使用該假設證明 $n=k+1$；寫出對指定範圍成立的結論。"
          },
          {
            "id": "concept-own-math2-1-1-c10-b2",
            "position": 1,
            "block_type": "warning",
            "title": "必須使用假設",
            "content_md": "只分別寫出第 k 與第 k+1 個式子，或只驗算數個值，都不是完整歸納證明。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:35:26.767Z"
      },
      {
        "skeleton_id": "1-1-C11",
        "id": "concept-own-math2-1-1-c11",
        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "歸納驗證遞迴一般項",
        "summary_md": "由遞迴式列項形成猜測後，以歸納法證明候選一般項。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c11-b1",
            "position": 0,
            "block_type": "method",
            "title": "遞迴歸納步",
            "content_md": "證明 $k+1$ 時，先以遞迴式寫出 $a_{k+1}$，再把 $a_k$ 換成歸納假設。"
          },
          {
            "id": "concept-own-math2-1-1-c11-b2",
            "position": 1,
