        "unit_id": "unit-math2-ch1-1-1",
        "title": "線性複合與可變換遞迴",
        "summary_md": "藉由固定點平移或倒數代換，可把非基本外觀轉成等差或等比數列。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c08-b1",
            "position": 0,
            "block_type": "formula",
            "title": "固定點平移",
            "content_md": "對 $a_{n+1}=pa_n+q$，取 $\\alpha=p\\alpha+q$，令 $b_n=a_n-\\alpha$，則 $b_{n+1}=pb_n$。"
          },
          {
            "id": "concept-own-math2-1-1-c08-b2",
            "position": 1,
            "block_type": "method",
            "title": "倒數代換",
            "content_md": "若分式遞迴含 $\\frac{a_n}{1+ca_n}$，可嘗試令 $b_n=\\frac{1}{a_n}$。"
          },
          {
            "id": "concept-own-math2-1-1-c08-b3",
            "position": 2,
            "block_type": "warning",
            "title": "還原條件",
            "content_md": "代換前後都要檢查分母非零，以及所得公式是否也適用首項。"
          }
        ],
        "created_at": "2026-07-27T18:27:29.474Z",
        "updated_at": "2026-07-29T09:44:58.208Z"
      },
      {
