        "grade_id": "11111111-1111-4111-8111-111111111111",
        "unit_id": "unit-math2-ch1-1-1",
        "title": "複利與等比型成長",
        "summary_md": "複利把每期本利和作為下一期本金，因此相鄰兩期固定乘上 $1+r$。",
        "status": "reviewed",
        "visibility": "private",
        "created_by_auth_type": "codex",
        "created_by_key_name": "original-lecture-authoring",
        "created_by_label": "本機原創講義",
        "blocks": [
          {
            "id": "concept-own-math2-1-1-c15-b1",
            "position": 0,
            "block_type": "formula",
            "title": "複利模型",
            "content_md": "本金為 $P$、每期利率為 $r$ 時，第 $n$ 期末本利和為 $A_n=P(1+r)^n$。"
          },
          {
            "id": "concept-own-math2-1-1-c15-b2",
            "position": 1,
            "block_type": "method",
            "title": "期數判斷",
            "content_md": "先比較 $P(1+r)^n$ 與目標金額；若題目問「至少」或「首次達到」，須選最小符合條件的正整數 $n$。"
          },
          {
            "id": "concept-own-math2-1-1-c15-b3",
            "position": 2,
            "block_type": "warning",
            "title": "單利與複利",
            "content_md": "單利是固定增加量，複利是固定倍率；不可把兩種模型的公式混用。"
          }
        ],
        "created_at": "2026-07-29T06:36:43.236Z",
        "updated_at": "2026-07-29T09:44:58.208Z"
      },
